head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}


scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정
    let cStyle = scwin.gVar["cStyle"];
    cStyle += "width:150px; height:30px;"
    let cStyleParent = scwin.gVar["cStyleParent"];

    // parent 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strParent = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp
    );

    // createBasicPageControl(고정 style) 대신 pageControl 를 직접 생성 (parent1 하위, cStyle=con_style_target 반영 -> setPosition 동작)
    let strTarget = '<w2:pageControl ' + strNameSpace + ' style="' + cStyle + '"></w2:pageControl>';

    // base(common_M)가 objParent.scwin.target1 로 접근하므로 scwin.target1 에 생성된 pageControl 를 설정 (parent1 하위에 생성)
    scwin.target1 = await $p.dynamicCreate('target1', "pageControl", strTarget, parent1);
}
